const $ = (s) => document.querySelector(s);
const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',chat:'<path d="M21 11.5a9 9 0 0 1-9 9 10 10 0 0 1-4-.9L3 21l1.4-4.5A9 9 0 1 1 21 11.5Z"/><path d="M8 10h8m-8 4h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',gift:'<path d="M3 8h18v4H3zM5 12v9h14v-9M12 8v13"/><path d="M12 8S4 9 6 4s6 4 6 4 6-9 6-4-6 4-6 4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon = n => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n] || icons.spark}</svg>`;
const brand = '<a class="brand" href="/"><img class="brand-mark" src="/assets/logo.svg" alt=""><span>JJ <b>TrendZ</b><small>YOUR EVERYDAY SPARKLE</small></span></a>';
const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
function read(key,fallback){try{return JSON.parse(localStorage.getItem('jj-'+key)) ?? fallback;}catch{return fallback;}}
let products=[], saved=read('saved',[]), bag=read('bag',[]), legacyQuantities=read('quantities',{}), inquiries=[], orders=[], contact={name:'JJ TrendZ',email:'',phone:'',hours:''}, bulk={tiers:[]}, customer=null, heroImage='/assets/hero.jpg', heroCopy={eyebrow:'THE EVERYDAY SPARKLE EDIT',headline:'A little sparkle.',highlight:'A lot of you.',description:'For the everyday moments and the unforgettable ones. Discover jewellery that feels like you.'}, checkoutSettings={upiId:'',payeeName:'ABHISHEK S',deliveryFee:0}, pendingOtp=null, customerOrderSnapshot='';
let category='All jewellery', collection='All', query='', sort='featured', colorFilter='', sizeFilter='', materialFilter='', occasionFilter='', priceMin='', priceMax='', stockOnly=false, saleOnly=false, adminTab='products', owner=false, ownerProducts=[], editorPhotos=[], recent=read('recent',[]);
function colorsFor(p){return Array.isArray(p.colors)&&p.colors.length?p.colors:['Gold'];}
function sizesFor(p){return Array.isArray(p.sizes)&&p.sizes.length?p.sizes:p.category==='Bangles'?['42','44','46','48']:p.category==='Earrings'?['One size']:['Free size'];}
function defaultSizes(category){return category==='Bangles'?['42','44','46','48']:category==='Earrings'?['One size']:['Free size'];}
function parseOptions(value,label){const list=value.split(',').map(s=>s.trim()).filter(Boolean);if(!list.length||list.length>12||list.some(s=>s.length>30)||new Set(list.map(s=>s.toLowerCase())).size!==list.length)throw new Error('Enter 1–12 unique '+label+', separated by commas (up to 30 characters each).');return list;}
function normalizeBag(){if(!Array.isArray(bag)){bag=[];persist('bag',bag);return;}let changed=false;bag=bag.flatMap(entry=>{const id=typeof entry==='string'?entry:entry?.id;const p=products.find(item=>item.id===id);if(!p)return [];if(typeof entry==='string'){changed=true;return [{id,color:colorsFor(p)[0],size:sizesFor(p)[0],quantity:Math.max(1,Math.min(9999,Number(legacyQuantities[id])||1))}];}return [{id,color:entry.color||colorsFor(p)[0],size:entry.size||sizesFor(p)[0],quantity:Number.isInteger(entry.quantity)?entry.quantity:1}];});if(changed)persist('bag',bag);}
function filterOptions(){
  const relevant=products.filter(p=>(category==='All jewellery'||category==='Festive edit'&&p.collection==='Festive'||category==='New arrivals'&&p.badge==='NEW ARRIVAL'||category==='Sale'&&p.onSale||p.category===category)&&(collection==='All'||p.collection===collection));
  const options=key=>[...new Set(relevant.flatMap(p=>key==='colors'?colorsFor(p):key==='sizes'?sizesFor(p):p[key]?[p[key]]:[]))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
  const colors=options('colors'),sizes=options('sizes'),materials=options('material'),occasions=options('occasion');
  if(colorFilter&&!colors.includes(colorFilter))colorFilter='';
  if(sizeFilter&&!sizes.includes(sizeFilter))sizeFilter='';
  if(materialFilter&&!materials.includes(materialFilter))materialFilter='';
  if(occasionFilter&&!occasions.includes(occasionFilter))occasionFilter='';
  const select=(id,label,all,choices,value)=>`<label>${label}<select id="${id}"><option value="">${all}</option>${choices.map(c=>`<option value="${esc(c)}" ${c===value?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;
  const node=$('#variant-filters');if(!node)return;
  const selected=[['color',colorFilter],['size',sizeFilter],['material',materialFilter],['occasion',occasionFilter],['price-min',priceMin?'From '+money(Number(priceMin)):''],['price',priceMax?'Under '+money(Number(priceMax)):''],['stock',stockOnly?'In stock':''],['sale',saleOnly?'On sale':'']].filter(([,value])=>value);
  const summary=$('.filter-panel>summary');if(summary)summary.textContent=`Filter products${selected.length?` (${selected.length} applied)`:''}`;
  node.innerHTML=`${select('filter-color','Colour','All colours',colors,colorFilter)}${select('filter-size','Size','All sizes',sizes,sizeFilter)}${select('filter-material','Material','All materials',materials,materialFilter)}${select('filter-occasion','Occasion','All occasions',occasions,occasionFilter)}<label>Min price (₹)<input id="filter-price-min" type="number" min="1" step="1" placeholder="Any price" value="${esc(priceMin)}"></label><label>Max price (₹)<input id="filter-price" type="number" min="1" step="1" placeholder="Any price" value="${esc(priceMax)}"></label><label class="filter-check"><input id="filter-stock" type="checkbox" ${stockOnly?'checked':''}> In stock</label><label class="filter-check"><input id="filter-sale" type="checkbox" ${saleOnly?'checked':''}> On sale</label>${selected.length?`<div class="filter-chips" aria-label="Applied filters">${selected.map(([key,value])=>`<button type="button" data-filter-remove="${key}" aria-label="Remove ${esc(value)} filter">${esc(value)} ×</button>`).join('')}</div><button class="text-link" data-action="clear-filters">Clear filters</button>`:''}`;
}

const stockKey=(color,size)=>JSON.stringify([color,size]);
const variantStock=(p,color,size)=>{const value=p.stock?.[stockKey(color,size)];return Number.isInteger(value)&&value>=0?value:null;};
const hasAnyStock=p=>colorsFor(p).some(color=>sizesFor(p).some(size=>variantStock(p,color,size)>0));
const allTracked=p=>colorsFor(p).every(color=>sizesFor(p).every(size=>variantStock(p,color,size)!==null));
function stockLabel(p){return hasAnyStock(p)?'In stock':allTracked(p)?'Sold out':'Stock not set';}
function refreshAvailability(p){
  const node=$('#variant-availability');if(!node)return;
  const remaining=variantStock(p,$('#chosen-color').value,$('#chosen-size').value);
  node.textContent=remaining===null?'Stock not set for this colour and size':remaining===0?'Sold out in this colour and size':remaining<=5?`Only ${remaining} available`:'In stock';
  const add=$('[data-add]');if(add)add.disabled=remaining===null||remaining===0;
}
function recommendProducts(p,key){
  const chosen=key==='recent'?recent.filter(id=>id!==p.id):p[key]||[];
  const selected=chosen.map(id=>products.find(item=>item.id===id)).filter(Boolean).slice(0,4);
  if(selected.length)return selected;
  if(key==='recent')return [];
  const sameCategory=key==='relatedIds';
  return products.filter(item=>item.id!==p.id&&(sameCategory?item.category===p.category:item.category!==p.category))
    .sort((a,b)=>(Number(b.occasion===p.occasion)+Number(colorsFor(b).some(color=>colorsFor(p).includes(color))))-(Number(a.occasion===p.occasion)+Number(colorsFor(a).some(color=>colorsFor(p).includes(color)))))
    .slice(0,4);
}
function recommendRow(p,key,title){const items=recommendProducts(p,key);return items.length?`<section class="recommend-row"><h3>${title}</h3><div class="recommend-grid">${items.map(item=>`<button type="button" data-product="${item.id}"><img src="${esc(item.image)}" alt="${esc(item.name)}"><span>${esc(item.name)}</span><strong>${money(item.displayPrice??item.price)}</strong></button>`).join('')}</div></section>`:'';}
const isOwner=location.pathname.replace(/\/$/,'')==='/owner';
function persist(key,value){try{localStorage.setItem('jj-'+key,JSON.stringify(value));return true;}catch{toast('Browser storage is full or unavailable. Your changes could not be saved.');return false;}}
let hostedUploads=false, policies={};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(content,wide=false){const d=$('#modal');d.className=wide?'detail-dialog':'';d.innerHTML=`<button class="modal-close" data-action="close" aria-label="Close dialog">${icon('close')}</button>${content}`;if(!d.open)d.showModal();}
function header(){return `<div class="announcement">A little sparkle. A lot of you. <span>✦</span> Discover your next favourite</div><header class="header wrap">${brand}<form class="search" id="search-form"><input name="search" aria-label="Search jewellery" placeholder="Search for your kind of sparkle…" value="${esc(query)}"><button aria-label="Search">${icon('search')}</button></form><div class="header-actions"><button class="icon-button" data-action="account">${icon('user')}<span>${customer?esc(customer.name.split(' ')[0]):'Account'}</span></button><button class="icon-button" data-action="wishlist">${icon('heart')}<span>Wishlist</span>${saved.length?`<b class="count">${saved.length}</b>`:''}</button><button class="icon-button" data-action="bag">${icon('bag')}<span>My bag</span>${bag.length?`<b class="count">${bag.length}</b>`:''}</button></div></header><nav class="nav"><div class="nav-inner wrap"><button data-action="bulk" class="special">Bulk orders ↗</button>${['All jewellery','Necklaces','Earrings','Bridal Sets','Bangles','New arrivals','Sale','Festive edit'].map(c=>`<button data-category="${c}" class="${category===c?'active ':''}${c==='Festive edit'?'special':''}">${c}${c==='Festive edit'?' ✧':''}</button>`).join('')}</div></nav>`;}
function storefront(){ $('#app').innerHTML=`${header()}<main><section class="hero"><div class="hero-copy"><span class="eyebrow">${esc(heroCopy.eyebrow)}</span><h1>${esc(heroCopy.headline)}<br><em>${esc(heroCopy.highlight)}</em></h1><p>${esc(heroCopy.description)}</p><button class="primary" data-action="shop">Explore the collection ${icon('arrow')}</button><div class="hero-bottom">${icon('spark')} LITTLE DETAILS. BEAUTIFUL POSSIBILITIES.</div></div><div class="hero-photo"><img src="${esc(heroImage)}" alt="JJ TrendZ featured jewellery"><button class="photo-note" data-action="shop">${icon('spark')}<span>Your everyday, elevated.<small>EXPLORE THE COLLECTION →</small></span></button></div></section><div class="perks wrap">${[['spark','Styles for every occasion'],['gift','Find a thoughtful gift'],['heart','Save the pieces you love'],['chat','Personal help, just a message away']].map(([i,t])=>`<div class="perk">${icon(i)}${t}</div>`).join('')}</div><section class="section wrap"><div class="section-head"><div><span class="eyebrow">FIND YOUR KIND OF BEAUTIFUL</span><h2>A little something for everyone</h2><p>From everyday essentials to your main-character moments.</p></div><button class="text-link" data-category="All jewellery">Shop all jewellery <span>↗</span></button></div><div class="categories">${[['Necklaces','jewel-1.jpg','Free-size layers'],['Earrings','hero.jpg','A finishing touch'],['Bridal Sets','bridal-set.jpg','For your big day'],['Bangles','bangles.jpg','Find your fit'],['Festive edit','jewel-4.jpg','Made for moments']].map(([c,img,sub])=>`<button class="category" data-category="${c}"><div class="category-img"><img src="/assets/${img}" alt="${c}" loading="lazy"></div><span>${c}</span><small>${sub}</small></button>`).join('')}</div></section><section class="section wrap" id="collection"><div class="section-head"><div><span class="eyebrow">CURATED WITH LOVE</span><h2 id="collection-title">Pieces to fall in love with</h2><p id="collection-subtitle">Your next favourite is waiting to be discovered.</p></div><span class="text-link" id="result-count"></span></div><div class="collection-top"><div class="tabs">${['All','Everyday','Occasion','Festive'].map(c=>`<button class="tab ${collection===c?'active':''}" data-collection="${c}">${c==='All'?'All favourites':c+' jewellery'}</button>`).join('')}</div><select class="sort" id="sort" aria-label="Sort products"><option value="featured">Sort by: Featured</option><option value="low">Price: Low to high</option><option value="high">Price: High to low</option><option value="new">Newest first</option><option value="discount">Biggest discount</option></select></div><details class="filter-panel" open><summary>Filter products</summary><div class="variant-filters" id="variant-filters"></div></details><div class="product-grid" id="products"></div></section><section class="story wrap"><img src="/assets/jewel-1.jpg" alt="Delicate layered necklaces styled with a white outfit" loading="lazy"><div class="story-copy"><span class="eyebrow">THE JJ TRENDZ FEELING</span><h2>More than an accessory.<br>A little piece of you.</h2><p>We believe the best jewellery is the kind you reach for again and again. Thoughtfully chosen styles for your story, your mood, and your moments.</p><button class="text-link" data-action="shop">Find your signature piece <span>↗</span></button></div></section><section class="contact-strip wrap"><div><h3>A little help finding your sparkle?</h3><p>Questions about a piece? Get in touch. We’d love to help.</p></div><button class="secondary" data-action="contact">${icon('chat')} Talk to us ${icon('arrow')}</button></section></main><footer><div class="footer-grid wrap"><div>${brand}<p>A thoughtfully curated world of jewellery.<br>For your everyday and extraordinary.</p></div><div><h4>Explore</h4>${['All jewellery','Necklaces','Earrings','Bridal Sets','Bangles'].map(c=>`<button data-category="${c}">${c}</button>`).join('')}</div><div><h4>Here to help</h4><button data-action="contact">Contact us</button><button data-action="care">Jewellery care</button><button data-action="delivery">Delivery & returns</button><button data-action="account">My account</button><button data-action="privacy">Privacy</button><button data-action="terms">Terms</button></div><div><h4>Let’s stay connected</h4><button data-action="contact">${icon('chat')} Ask about a piece</button><p>${esc(contact.hours)}<br>${contact.email?esc(contact.email):'A personal touch, always.'}</p></div></div><div class="copyright wrap"><span>© ${new Date().getFullYear()} JJ TrendZ. All rights reserved.</span><span>Made for your kind of beautiful. ✧</span></div></footer><button class="floating-contact" data-action="contact" aria-label="Contact JJ TrendZ">${icon('chat')}<span>Let’s talk jewellery</span></button>`;if(matchMedia("(max-width:700px)").matches) $(".filter-panel").open=false;updateProducts();}
function visibleProducts(){
  let list=products.filter(p=>(category==='All jewellery'||category==='Festive edit'&&p.collection==='Festive'||category==='New arrivals'&&p.badge==='NEW ARRIVAL'||category==='Sale'&&p.onSale||p.category===category)
    &&(collection==='All'||p.collection===collection)
    &&(!colorFilter||colorsFor(p).includes(colorFilter))&&(!sizeFilter||sizesFor(p).includes(sizeFilter))
    &&(!materialFilter||p.material===materialFilter)&&(!occasionFilter||p.occasion===occasionFilter)
    &&(!priceMin||p.displayPrice>=Number(priceMin))&&(!priceMax||p.displayPrice<=Number(priceMax))&&(!saleOnly||p.onSale)
    &&(!stockOnly||hasAnyStock(p))
    &&`${p.name} ${p.caption} ${p.category} ${p.material||''} ${p.occasion||''}`.toLowerCase().includes(query.toLowerCase()));
  const featured=(a,b)=>(a.featuredRank||999)-(b.featuredRank||999)||String(b.createdAt||'').localeCompare(String(a.createdAt||''));
  if(sort==='low')list.sort((a,b)=>a.displayPrice-b.displayPrice);
  else if(sort==='high')list.sort((a,b)=>b.displayPrice-a.displayPrice);
  else if(sort==='new')list.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
  else if(sort==='discount')list.sort((a,b)=>(b.onSale?1-b.displayPrice/b.oldPrice:0)-(a.onSale?1-a.displayPrice/a.oldPrice:0));
  else list.sort(featured);
  return list;
}
function updateProducts(){
  filterOptions();
  const list=visibleProducts();
  $('#products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="product-media"><button class="product-open" data-product="${p.id}" aria-label="View ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"></button>${p.onSale?'<span class="badge sale-badge">SALE</span>':p.badge?`<span class="badge">${esc(p.badge)}</span>`:''}<button class="wish ${saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><span class="eyebrow">${esc(p.category)} · ${esc(p.collection)}</span><button class="product-name" data-product="${p.id}">${esc(p.name)}</button>${price(p)}<span class="size-note">${esc([p.material,p.plating].filter(Boolean).join(' · ')||colorsFor(p).join(' · '))}</span><span class="stock-label ${hasAnyStock(p)?'':'stock-muted'}">${stockLabel(p)}</span><div class="product-foot"><span>${bag.some(line=>line.id===p.id)?'In your bag':'See details'}</span><button data-enquire="${p.id}">Enquire ${icon('arrow')}</button></div></div></article>`).join(''):`<div class="empty">${icon('search')}<p>No pieces match your filters.</p><button class="secondary" data-action="reset">Browse all jewellery</button></div>`;
  $('#result-count').textContent=`${list.length} pieces`;
  $('#collection-title').textContent=query?`Results for “${query}”`:category==='All jewellery'?'Pieces to fall in love with':category;
  $('#collection-subtitle').textContent=query?'Find something that speaks to you.':'Use the filters to find the right piece, size and price.';
  document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));
  document.querySelectorAll('[data-collection]').forEach(b=>b.classList.toggle('active',b.dataset.collection===collection));
  $('#sort').value=sort;
}
function price(p){
  const selling=p.displayPrice??p.price;
  return `<div class="price"><strong>${money(selling)}</strong>${p.onSale?`<del>${money(p.oldPrice)}</del><span class="discount">${Math.round((1-selling/p.oldPrice)*100)}% off</span>`:''}</div>`;
}
function detail(id){
  const p=products.find(item=>item.id===id);if(!p)return;
  recent=[id,...recent.filter(value=>value!==id)].slice(0,8);persist('recent',recent);
  const images=p.images?.length?p.images:[p.image];
  const spec=(label,value)=>value?`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`:'';
  const gallery=`<div class="product-gallery"><img id="detail-photo" class="detail-main-image" src="${esc(images[0])}" alt="${esc(p.name)}"><div class="gallery-thumbs">${images.map((src,index)=>`<button type="button" class="gallery-thumb ${index===0?'active':''}" data-gallery="${index}" aria-label="View photo ${index+1} of ${esc(p.name)}"><img src="${esc(src)}" alt=""></button>`).join('')}</div></div>`;
  modal(`<div class="detail">${gallery}<div class="detail-copy"><span class="eyebrow">${esc(p.category)} · ${esc(p.collection)}</span><h2>${esc(p.name)}</h2>${price(p)}<p>${esc(p.caption)}</p><dl class="product-specs">${spec('Material',p.material)}${spec('Plating',p.plating)}${spec('Size / dimensions',p.dimensions||(['Necklaces','Bridal Sets','Bangles'].includes(p.category)?'Ask us for exact measurements before ordering.':''))}${spec('Included',p.included)}${spec('Care',p.care)}</dl><div class="variant-pickers"><label class="field">Colour<select id="chosen-color">${colorsFor(p).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label class="field">Size<select id="chosen-size">${sizesFor(p).map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label></div>${p.category==='Bangles'?'<details class="fit-guide"><summary>How do I check my bangle size?</summary><p>Measure the inside diameter of a bangle that fits you, straight across the opening. Compare that measurement with this product’s dimensions, or ask us to confirm the right size before ordering.</p></details>':''}<p id="variant-availability" class="stock-label"></p><p class="detail-meta">${esc(p.dispatchNote||'Delivery timing is confirmed after your order is placed.')}<br>Product code: ${esc(p.id.toUpperCase())}</p><button class="primary" data-add="${p.id}">${icon('bag')} Add to bag</button><button class="secondary" data-enquire="${p.id}">${icon('chat')} Enquire about this piece</button><button class="text-link" data-save="${p.id}">${saved.includes(id)?'Saved to wishlist':'Save to wishlist'} ♡</button></div></div>${recommendRow(p,'relatedIds','Similar pieces')}${recommendRow(p,'pairWithIds','Complete the look')}${recent.length>1?recommendRow(p,'recent','Recently viewed'):''}`,true);
  refreshAvailability(p);
}
let authMode='login';
function account(){if(customer){modal(`<span class="eyebrow">YOUR LITTLE WORLD OF SPARKLE</span><h2>Hello, ${esc(customer.name)}.</h2><p>${esc(customer.email)}</p><button class="secondary full" data-action="wishlist">View your wishlist</button><br><br><button class="secondary full" data-action="orders">My orders</button><br><br><button class="text-link" data-action="signout">Sign out</button>`);return;}modal(`<span class="eyebrow">WELCOME TO JJ TRENDZ</span><h2>${authMode==='register'?'Make yourself at home.':'Welcome back.'}</h2><p>${authMode==='register'?'Create your account to place orders and track your pieces.':'Sign in to your jewellery collection.'}</p><form id="customer-form">${authMode==='register'?'<label class="field">Your name<input name="name" required autocomplete="name" maxlength="60"></label>':''}<label class="field">Email address<input name="email" type="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="${authMode==='register'?'new-password':'current-password'}"></label><p class="form-error" role="alert"></p><button class="primary full">${authMode==='register'?'Create account':'Sign in'}</button></form><p>${authMode==='register'?'Already have an account?':'New to JJ TrendZ?'} <button class="text-link" data-action="${authMode==='register'?'login':'register'}">${authMode==='register'?'Sign in':'Create an account'}</button></p><button class="text-link" data-action="reset-password">Forgot password?</button>`);}
function otpDialog(){if(!pendingOtp)return;modal(`<span class="eyebrow">ONE MORE STEP</span><h2>Check your email.</h2><p>${pendingOtp.preview?'A six-digit code for':'We sent a six-digit code to'} <strong>${esc(pendingOtp.email)}</strong>${pendingOtp.preview?' was saved in the local outbox.':'.'} It expires in 10 minutes.</p>${pendingOtp.preview?'<p class="form-note">Open <code>data/mail-outbox.jsonl</code> on this computer to read the code.</p>':''}<form id="otp-form"><label class="field">Verification code<input name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="one-time-code" required autofocus placeholder="123456"></label><p class="form-error" role="alert"></p><button class="primary full">Verify email and sign in</button></form><p><button class="text-link" data-action="otp-back">Start again</button></p>`);}
function cartItems(){return bag.map((line,index)=>{const p=products.find(item=>item.id===line.id);if(!p)return null;const remaining=variantStock(p,line.color,line.size);return {...p,color:line.color,size:line.size,quantity:line.quantity,index,remaining,unavailable:!colorsFor(p).includes(line.color)||!sizesFor(p).includes(line.size)||remaining===null||remaining<line.quantity};}).filter(Boolean);}
function cartTotal(){
  const items=cartItems(),quantity=items.reduce((sum,p)=>sum+p.quantity,0);
  const subtotal=items.reduce((sum,p)=>sum+(p.displayPrice??p.price)*p.quantity,0);
  const saleSavings=items.reduce((sum,p)=>sum+(p.onSale?p.oldPrice-p.displayPrice:0)*p.quantity,0);
  const discount=bulk.tiers.filter(t=>quantity>=t.quantity).at(-1)?.discount||0;
  const total=Math.round(subtotal*(1-discount/100)),deliveryFee=checkoutSettings.deliveryFee||0;
  return {quantity,subtotal,saleSavings,discount,bulkSavings:subtotal-total,total,deliveryFee,payableTotal:total+deliveryFee};
}
function listModal(type){
  const list=type==='bag'?cartItems():saved.map(id=>products.find(p=>p.id===id)).filter(Boolean),t=cartTotal();
  modal(`<span class="eyebrow">THE PIECES YOU LOVE</span><h2>${type==='bag'?'Your shopping bag':'Your wishlist'}</h2>
    ${list.length?list.map(p=>`<div class="list-item"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><button data-product="${p.id}"><h3>${esc(p.name)}</h3></button>${price(p)}${type==='bag'?`<span class="size-note">${esc(p.color)} · ${esc(p.size)}</span>${p.unavailable?'<p class="variant-warning">This choice has no available owner-set stock or exceeds current stock. Change the quantity or remove it.</p>':''}<label class="quantity-label">Quantity <input type="number" class="quantity-input" data-quantity="${p.index}" min="1" max="${p.remaining??9999}" value="${p.quantity}"></label>`:`<span class="size-note">${esc(colorsFor(p).join(' · '))} · ${esc(sizesFor(p).join(' / '))}</span><button class="text-link" data-product="${p.id}">Choose options</button>`}</div><button ${type==='bag'?`data-remove-line="${p.index}"`:`data-remove="${p.id}" data-list="wishlist"`} aria-label="Remove ${esc(p.name)}">${icon('close')}</button></div>`).join(''):`<div class="empty">${icon(type==='bag'?'bag':'heart')}<p>${type==='bag'?'Your bag is waiting for a little sparkle.':'Save the pieces that catch your eye.'}</p><button class="primary" data-action="shop">Explore jewellery ${icon('arrow')}</button></div>`}
    ${list.length&&type==='bag'?`<div class="price-summary"><p><span>Products (${t.quantity} pieces)</span><strong>${money(t.subtotal)}</strong></p>${t.saleSavings?`<p class="savings"><span>Saved against regular prices (already included)</span><strong>${money(t.saleSavings)}</strong></p>`:''}${t.discount?`<p class="savings"><span>Bulk discount · ${t.discount}% on sale prices</span><strong>−${money(t.bulkSavings)}</strong></p>`:'<p class="muted-line">Bulk discount applies when your quantity reaches a listed tier.</p>'}<p><span>Delivery</span><strong>${money(t.deliveryFee)}</strong></p><p class="summary-total"><span>Total to pay</span><strong>${money(t.payableTotal)}</strong></p></div><button class="primary full" data-action="checkout">Place this order ${icon('arrow')}</button><p class="form-note">Only pieces with owner-set stock can be ordered. Pay by UPI after placing the order, or request a Razorpay link.</p>`:''}`);
}
function enquiry(ids=[],details=''){const selected=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean);modal(`<span class="eyebrow">WE’RE HERE TO HELP</span><h2>Let’s talk jewellery.</h2><div class="contact-card"><strong>${esc(contact.name)}</strong><br>${esc(contact.hours)}${contact.email?`<br><a href="mailto:${esc(contact.email)}">${esc(contact.email)}</a>`:''}${contact.phone?`<br><a href="tel:${esc(contact.phone)}">${esc(contact.phone)}</a>`:''}</div>${selected.length?`<p>About: <strong>${selected.map(p=>esc(p.name)).join(', ')}</strong></p>`:''}<form id="inquiry-form" data-ids="${esc(ids.join(','))}"><div class="row"><label class="field">Your name<input name="name" required value="${esc(customer?.name||'')}" autocomplete="name" maxlength="60"></label><label class="field">Email address<input name="email" type="email" required value="${esc(customer?.email||'')}" autocomplete="email"></label></div><label class="field">Your question<textarea name="message" required maxlength="2000" placeholder="I’d love to know about availability, sizing, or delivery…">${esc(details)}</textarea></label><button class="primary full">Send enquiry ${icon('arrow')}</button></form><p class="form-note">Your question goes directly to the JJ TrendZ owner studio.</p>${contact.phone?`<a class="secondary full" href="https://wa.me/${contact.phone.replace(/\D/g,'')}?text=${encodeURIComponent('Hello JJ TrendZ! I would like to enquire about '+(selected.map(p=>p.name+' ('+p.id+')').join(', ')||'your jewellery')+'.')}" target="_blank" rel="noopener">Continue on WhatsApp ${icon('chat')}</a>`:''}`);}
function renderOwner(){ $('#app').innerHTML=`<header class="owner-header">${brand}<a class="text-link" href="/">View storefront ↗</a></header>${!owner?`<main class="owner-login"><span class="eyebrow">JJ TRENDZ · OWNER STUDIO</span><h1>A space for your business.</h1><p>Manage your collection and connect with your customers.</p><form id="owner-form"><label class="field">Owner email<input name="email" type="email" required autocomplete="username"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password"></label><p id="login-error" role="alert"></p><button class="primary full">Sign in to owner studio ${icon('arrow')}</button></form><p class="form-note">${hostedUploads?'Use your configured owner credentials. A verification code will be emailed to you.':'Use your configured owner credentials or the initial credentials in data/owner-access.txt.'}</p></main>`:`<main class="owner-shell"><div class="section-head"><div><span class="eyebrow">OWNER STUDIO</span><h2>Your collection, your way.</h2><p>A little care behind every beautiful piece.</p></div><button class="text-link" data-action="owner-signout">Sign out</button></div><div class="stats"><div class="stat">Pieces in your collection<strong>${ownerProducts.length}</strong></div><div class="stat">Customer enquiries<strong>${inquiries.length}</strong></div><div class="stat">Orders<strong>${orders.length}</strong></div></div><div class="admin-tabs">${['products','orders','inquiries','bulk','payment','homepage','policies','settings'].map(t=>`<button class="tab ${adminTab===t?'active':''}" data-admin="${t}">${({products:'Products',orders:'Orders',inquiries:'Enquiries',bulk:'Bulk discounts',payment:'Payment & delivery',homepage:'Homepage text',policies:'Shop policies',settings:'Contact & images'})[t]}</button>`).join('')}</div>${adminContent()}<p class="form-note">Your changes are saved to the server. The storefront refreshes automatically every 5 seconds.</p></main>`}`;}
function adminContent(){if(adminTab==='policies')return `<form id="policies-form"><h3>Shop policies</h3><p>Publish your actual business policies here. These appear in the storefront footer.</p>${[['privacy','Privacy'],['shipping','Delivery coverage and timing'],['returns','Returns, cancellations and refunds'],['terms','Terms']].map(([key,label])=>`<label class="field">${label}<textarea name="${key}" required maxlength="5000">${esc(policies[key]||'')}</textarea></label>`).join('')}<button class="primary">Save policies</button></form>`;
if(adminTab==='orders')return orderCards(orders,true);if(adminTab==='bulk')return bulkSettings();if(adminTab==='payment')return paymentSettingsForm();if(adminTab==='homepage')return homepageSettingsForm();if(adminTab==='settings')return `<h3>Your contact details</h3><p>These details appear in product enquiry dialogs. Enquiries are emailed to the contact email below, or your owner login email if it is empty.</p><form id="settings-form"><label class="field">Display name<input name="name" value="${esc(contact.name)}" required maxlength="80"></label><div class="row"><label class="field">Contact email<input name="email" type="email" value="${esc(contact.email)}"></label><label class="field">WhatsApp / phone with country code<input name="phone" type="tel" pattern="[+]?[0-9 ()-]{7,20}" placeholder="+91 …" value="${esc(contact.phone)}"></label></div><label class="field">Business hours<input name="hours" value="${esc(contact.hours)}" maxlength="120"></label><button class="primary">Save contact details ${icon('check')}</button></form><hr><h3>Homepage image</h3><p>Change the photo beside “A little sparkle. A lot of you.”</p><form id="hero-form"><img class="edit-preview hero-preview" id="hero-preview" src="${esc(heroImage)}" alt="Current homepage hero"><label class="field">Hero photograph<input name="heroPhoto" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG or WebP · up to 2 MB. A wide photo works best.</small></label><button class="primary">Save homepage image ${icon('check')}</button></form>${hostedUploads?'<hr><p>Owner credentials are managed in Vercel environment settings. Redeploy after changing them; run the migration if the email changed.</p>':`<hr><h3>Change your password</h3><form id="password-form"><label class="field">Current password<input name="current" type="password" required autocomplete="current-password"></label><label class="field">New password<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><button class="primary">Update password</button></form>`}`;
if(adminTab==='inquiries')return inquiries.length?inquiries.slice().reverse().map(i=>`<article class="inquiry"><small>${esc(new Date(i.created).toLocaleString('en-IN'))}</small><h3>${esc(i.name)}</h3><a href="mailto:${esc(i.email)}">${esc(i.email)}</a><p><strong>${esc(i.productNames||'General enquiry')}</strong></p><p>${esc(i.message)}</p>${i.emailSent===false?`<p>Email delivery pending</p><button class="secondary" data-email-inquiry="${esc(i.id)}">Retry email</button>`:''}</article>`).join(''):`<div class="empty">${icon('chat')}<p>No enquiries yet. Saved storefront enquiries will appear here.</p></div>`;
return `<div class="section-head"><h3>Your jewellery collection</h3><button class="primary" data-action="new-product">+ Add a piece</button></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Status</th><th>Stock</th><th>Collection</th><th>Manage</th></tr></thead><tbody>${ownerProducts.map(p=>`<tr><td><div class="admin-product"><img src="${esc(p.image)}" alt="${esc(p.name)}"><span>${esc(p.name)}</span></div></td><td>${esc(p.category)}</td><td>${money(p.displayPrice??p.price)}${p.oldPrice>p.price&&!p.onSale?' <small>(sale scheduled)</small>':''}</td><td>${p.status==="draft"?"Draft":"Live"}</td><td>${stockLabel(p)}</td><td>${esc(p.collection)}</td><td><button data-edit="${p.id}">Edit</button><button data-delete="${p.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;}
function editor(id){
  const p=ownerProducts.find(item=>item.id===id)||{name:'',category:'Earrings',price:'',oldPrice:'',caption:'',collection:'Everyday',badge:'',image:'',images:[],colors:['Gold'],sizes:['One size'],stock:{},status:'live',featuredRank:999};
  editorPhotos=[...(p.images?.length?p.images:p.image?[p.image]:[])];
  editorStock={...(p.stock||{})};
  const peers=ownerProducts.filter(item=>item.id!==p.id&&item.status!=='draft');
  const choices=(name,ids)=>`<fieldset class="relation-field"><legend>${name==='related'?'Similar pieces':'Complete the look'} <small>(up to 4)</small></legend><div class="relation-choices">${peers.map(item=>`<label><input type="checkbox" name="${name}" value="${esc(item.id)}" ${(ids||[]).includes(item.id)?'checked':''}> ${esc(item.name)}</label>`).join('')||'<p>Add more products to choose matches.</p>'}</div></fieldset>`;
  modal(`<span class="eyebrow">YOUR COLLECTION</span><h2>${id?'Edit this piece':'Add a little sparkle'}</h2><form id="product-form" data-id="${esc(id||'')}" data-revision="${p.revision||0}">
    <h3>Photos</h3><p>Add up to five JPG, PNG or WebP photos, each under 2 MB. The first photo is shown in the catalogue.</p><div id="editor-photo-list" class="editor-photo-list"></div><label class="field">Add photos<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label>
    <h3>Product and price</h3><label class="field">Product name<input name="name" required maxlength="100" value="${esc(p.name)}"></label>
    <div class="row"><label class="field">Selling price (₹)<input name="price" type="number" min="1" max="999999" step="1" required value="${p.price}"></label><label class="field">Regular price (₹, optional)<input name="oldPrice" type="number" min="0" max="999999" step="1" value="${p.oldPrice||''}"><small>Only use a real regular price. Sale and bulk discounts combine.</small></label></div>
    <div class="row"><label class="field">Sale starts<input name="saleStart" type="date" value="${esc(p.saleStart||'')}"></label><label class="field">Sale ends<input name="saleEnd" type="date" value="${esc(p.saleEnd||'')}"></label></div>
    <div class="row"><label class="field">Category<select name="category">${['Necklaces','Earrings','Bridal Sets','Bangles'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Collection<select name="collection">${['Everyday','Occasion','Festive'].map(c=>`<option ${p.collection===c?'selected':''}>${c}</option>`).join('')}</select></label></div>
    <div class="row"><label class="field">Occasion<input name="occasion" list="occasion-suggestions" maxlength="80" value="${esc(p.occasion||'')}" placeholder="Wedding, Daily wear, Gifting…"><datalist id="occasion-suggestions"><option value="Wedding"><option value="Daily wear"><option value="Festive"><option value="Party"><option value="Gifting"></datalist></label><label class="field">Featured order<input name="featuredRank" type="number" min="1" max="9999" step="1" value="${p.featuredRank||999}"><small>Lower numbers appear first.</small></label></div>
    <div class="row"><label class="field">Available colours<input name="colors" required value="${esc(colorsFor(p).join(', '))}" placeholder="Gold, Blue, Green"></label><label class="field">Available sizes<input name="sizes" required value="${esc(sizesFor(p).join(', '))}" placeholder="42, 44, 46"></label></div><p class="form-note">Separate colours and sizes with commas. Bangles can use 42, 44…; necklaces and bridal sets can use Free size.</p>
    <h3>Stock by colour and size</h3><p>Enter 0 for sold out. Leave a box empty to prevent orders for that choice until stock is set. Stock is reserved when an order is placed and restored if you cancel it.</p><div id="stock-inputs" class="stock-inputs"></div>
    <h3>Details customers need</h3><label class="field">Caption / description<textarea name="caption" required maxlength="1500">${esc(p.caption)}</textarea></label>
    <div class="row"><label class="field">Material<input name="material" maxlength="80" value="${esc(p.material||'')}" placeholder="Brass, alloy, 925 silver…"></label><label class="field">Plating / finish<input name="plating" maxlength="80" value="${esc(p.plating||'')}" placeholder="Gold plated…"></label></div>
    <label class="field">Size / dimensions<input name="dimensions" maxlength="160" value="${esc(p.dimensions||'')}" placeholder="Chain length 45 cm; pendant 2 cm…"></label>
    <label class="field">What's included<input name="included" maxlength="200" value="${esc(p.included||'')}" placeholder="Necklace, earrings and maang tikka…"></label>
    <label class="field">Care instructions<input name="care" maxlength="300" value="${esc(p.care||'')}" placeholder="Keep away from water and perfume…"></label>
    <label class="field">Dispatch and delivery note<input name="dispatchNote" maxlength="200" value="${esc(p.dispatchNote||'')}" placeholder="Delivery timing and charges confirmed before payment"></label>
    ${choices('related',p.relatedIds)}${choices('pairWith',p.pairWithIds)}
    <div class="row"><label class="field">Product label<select name="badge">${['','NEW ARRIVAL','EVERYDAY FAVOURITE','OCCASION EDIT','FESTIVE PICK'].map(c=>`<option value="${c}" ${p.badge===c?'selected':''}>${c||'No label'}</option>`).join('')}</select></label><label class="field">Visibility<select name="status"><option value="live" ${p.status!=='draft'?'selected':''}>Live</option><option value="draft" ${p.status==='draft'?'selected':''}>Draft</option></select></label></div><p class="form-error" role="alert"></p><button class="primary full">${id?'Save changes':'Add product'} ${icon('check')}</button></form>`,true);
  renderEditorPhotos();renderStockInputs();
}
let editorStock={};
function renderEditorPhotos(){
  const node=$('#editor-photo-list');if(!node)return;
  node.innerHTML=editorPhotos.length?editorPhotos.map((src,index)=>`<div class="editor-photo"><img src="${esc(src)}" alt="Product photo ${index+1}"><span>${index===0?'Catalogue photo':`Photo ${index+1}`}</span><div><button type="button" data-photo-up="${index}" aria-label="Move photo up" ${index===0?'disabled':''}>↑</button><button type="button" data-photo-down="${index}" aria-label="Move photo down" ${index===editorPhotos.length-1?'disabled':''}>↓</button><button type="button" data-photo-remove="${index}" aria-label="Remove photo">×</button></div></div>`).join(''):'<p class="form-note">No photos yet. Add at least one before saving.</p>';
}
function renderStockInputs(){
  const form=$('#product-form'),node=$('#stock-inputs');if(!form||!node)return;
  for(const input of node.querySelectorAll('[data-stock-key]'))editorStock[input.dataset.stockKey]=input.value===''?null:Number(input.value);
  let colors,sizes;
  try{colors=parseOptions(form.elements.colors.value,'colours');sizes=parseOptions(form.elements.sizes.value,'sizes');}
  catch{node.innerHTML='<p class="form-note">Enter valid colours and sizes to set stock.</p>';return;}
  node.innerHTML=colors.flatMap(color=>sizes.map(size=>{const key=stockKey(color,size),value=editorStock[key];return `<label class="field">${esc(color)} · ${esc(size)}<input data-stock-key="${esc(key)}" type="number" min="0" max="9999" step="1" placeholder="Not orderable" value="${Number.isInteger(value)?value:''}"></label>`;})).join('');
}
async function photoData(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024)throw new Error('Choose a JPG, PNG or WebP image under 2 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Unable to read this image.'));r.readAsDataURL(file);});}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.category){category=d.category;collection='All';colorFilter='';sizeFilter='';materialFilter='';occasionFilter='';priceMin='';priceMax='';stockOnly=false;saleOnly=false;query='';$('.search input').value='';updateProducts();$('#collection').scrollIntoView({behavior:'smooth'});}
if(d.collection){collection=d.collection;updateProducts();}
if(d.product)detail(d.product);
if(d.enquire){const color=$('#chosen-color')?.value,size=$('#chosen-size')?.value;enquiry([d.enquire],color&&size?'I am interested in '+color+', size '+size+'. ':'');}
if(d.save){const next=saved.includes(d.save)?saved.filter(id=>id!==d.save):[...saved,d.save];if(persist('saved',next)){saved=next;storefront();if($('#modal').open)detail(d.save);toast(saved.includes(d.save)?'Saved to your wishlist.':'Removed from wishlist.');}}
if(d.add){const p=products.find(p=>p.id===d.add);if(!p)return;const color=$('#chosen-color')?.value,size=$('#chosen-size')?.value;if(!color||!size){detail(p.id);return;}const remaining=variantStock(p,color,size);const already=bag.find(line=>line.id===p.id&&line.color===color&&line.size===size)?.quantity||0;if(remaining===null||already>=remaining){toast('Owner-set stock is required for this choice, or it is already fully in your bag.');return;}const index=bag.findIndex(line=>line.id===p.id&&line.color===color&&line.size===size);const next=bag.map(line=>({...line}));if(index>=0){if(next[index].quantity>=9999){toast('Maximum quantity reached.');return;}next[index].quantity++;}else next.push({id:p.id,color,size,quantity:1});if(!persist('bag',next))return;bag=next;storefront();toast('Added '+color+' · '+size+' to your bag.');}
if(d.removeLine!==undefined){const next=bag.filter((_,index)=>index!==Number(d.removeLine));if(!persist('bag',next))return;bag=next;storefront();listModal('bag');}
if(d.remove&&d.list==='wishlist'){const next=saved.filter(id=>id!==d.remove);if(!persist('saved',next))return;saved=next;storefront();listModal('wishlist');}
if(d.admin&&owner){adminTab=d.admin;renderOwner();}if(d.edit&&owner)editor(d.edit);
if(d.delete&&owner){const p=ownerProducts.find(p=>p.id===d.delete);modal(`<h2>Remove this piece?</h2><p>“${esc(p.name)}” will be removed from your collection.</p><button class="primary full" data-confirm-delete="${p.id}">Delete product</button><br><br><button class="secondary full" data-action="close">Keep product</button>`);}
if(d.confirmDelete&&owner){try{await api('/api/products/'+d.confirmDelete,{method:'DELETE'});await syncCatalog();await syncOwner();bag=bag.filter(line=>line.id!==d.confirmDelete);saved=saved.filter(id=>id!==d.confirmDelete);persist('bag',bag);persist('saved',saved);$('#modal').close();renderOwner();toast('Product removed.');}catch(err){toast(err.message);}}
if(d.emailInquiry&&owner){try{await api('/api/inquiries/'+d.emailInquiry,{method:'PATCH',body:{}});await syncOwner();renderOwner();toast('Enquiry emailed.');}catch(err){toast(err.message);}}
if(d.cancelOrder&&owner){const order=orders.find(item=>item.id===d.cancelOrder);if(order)modal(`<span class="eyebrow">CANCEL ORDER</span><h2>Cancel this order?</h2><p>Order #${esc(order.id.slice(0,8).toUpperCase())} will be cancelled and reserved stock will be restored.</p>${order.paymentLink?'<p class="form-note">Cancel the active payment link in your Razorpay dashboard first. Removing it from JJ TrendZ does not deactivate the Razorpay link.</p>':''}${order.paymentMethod==='UPI'?'<p class="form-note">Check your UPI or bank app first. A payment already in progress could arrive after cancellation.</p>':''}<button class="primary full" data-confirm-cancel="${esc(order.id)}">Cancel order</button><br><br><button class="secondary full" data-action="close">Keep order</button>`);}
if(d.confirmCancel&&owner){try{await api('/api/orders/'+d.confirmCancel,{method:'PATCH',body:{action:'cancel',reconciled:true}});await syncOwner();$('#modal').close();renderOwner();toast('Order cancelled.');}catch(err){toast(err.message);}}
if(d.emailOrder&&owner){try{const result=await api('/api/orders/'+d.emailOrder,{method:'PATCH',body:{action:'email-link'}});await syncOwner();renderOwner();toast(result.warning||'Payment link emailed to the customer.');}catch(err){toast(err.message);}}
if(d.emailTracking&&owner){try{const result=await api('/api/orders/'+d.emailTracking,{method:'PATCH',body:{action:'email-tracking'}});await syncOwner();renderOwner();toast(result.warning||'Tracking emailed to the customer.');}catch(err){toast(err.message);}}
switch(d.action){case 'close':$('#modal').close();break;case 'shop':$('#modal').close();$('#collection').scrollIntoView({behavior:'smooth'});break;case 'reset':category='All jewellery';collection='All';colorFilter='';sizeFilter='';materialFilter='';occasionFilter='';priceMin='';priceMax='';stockOnly=false;saleOnly=false;query='';$('.search input').value='';updateProducts();break;case 'account':account();break;case 'wishlist':listModal('wishlist');break;case 'bag':listModal('bag');break;case 'bag-enquire':enquiry(bag.map(line=>line.id));break;case 'bulk':bulkModal();break;case 'checkout':checkout();break;case 'clear-filters':colorFilter='';sizeFilter='';materialFilter='';occasionFilter='';priceMin='';priceMax='';stockOnly=false;saleOnly=false;updateProducts();break;case 'otp-back':pendingOtp=null;account();break;case 'reset-password':modal('<h2>Reset your password</h2><p>We will email a verification code if a customer account exists.</p><form id="reset-form"><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">New password<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><p role="alert"></p><button class="primary">Send verification code</button></form>');break;case 'privacy':case 'terms':modal(`<h2>${d.action==='privacy'?'Privacy':'Terms'}</h2><p style="white-space:pre-wrap">${esc(policies[d.action]||'Contact JJ TrendZ for details before ordering.')}</p>`);break;case 'register':authMode='register';account();break;case 'login':authMode='login';account();break;case 'orders':await showOrders();break;case 'contact':enquiry();break;case 'signout':case 'owner-signout':try{await api('/api/logout',{method:'POST'});customer=null;owner=false;$('#modal').close();if(isOwner)renderOwner();else storefront();toast('Signed out.');}catch(err){toast(err.message);}break;case 'new-product':if(owner)editor();break;case 'care':modal('<span class="eyebrow">A LITTLE CARE GOES A LONG WAY</span><h2>Keep your sparkle.</h2><p>Store your jewellery separately in a soft pouch. Avoid direct contact with perfume, water, and harsh cleaning products. Gently wipe each piece with a soft, dry cloth after wearing.</p><p>For material-specific care, enquire about your chosen piece.</p>');break;case 'delivery':modal(`<h2>Delivery & returns</h2><h3>Delivery</h3><p style="white-space:pre-wrap">${esc(policies.shipping||'Contact JJ TrendZ to confirm delivery charges and timing.')}</p><h3>Returns & cancellations</h3><p style="white-space:pre-wrap">${esc(policies.returns||'Contact JJ TrendZ to confirm return eligibility before ordering.')}</p><button class="primary full" data-action="contact">Ask us a question</button>`);break;}
});
document.addEventListener('change',async e=>{if(e.target.dataset.quantity!==undefined){const qty=Number(e.target.value),index=Number(e.target.dataset.quantity);if(!Number.isInteger(qty)||qty<1||qty>9999||!bag[index]){toast('Choose a quantity from 1 to 9999.');return;}const line=bag[index],product=products.find(p=>p.id===line.id),remaining=product&&variantStock(product,line.color,line.size);if(remaining===null||remaining!==undefined&&qty>remaining){toast(remaining===null?'Stock is not set for this choice.':'Only '+remaining+' available in this choice.');listModal('bag');return;}const next=bag.map(line=>({...line}));next[index].quantity=qty;if(!persist('bag',next))return;bag=next;listModal('bag');}if(e.target.id==='sort'){sort=e.target.value;updateProducts();}if(e.target.id==='filter-color'){colorFilter=e.target.value;updateProducts();}if(e.target.id==='filter-size'){sizeFilter=e.target.value;updateProducts();}if(e.target.name==='category'&&e.target.closest('#product-form')){const field=e.target.closest('#product-form').elements.sizes;field.value=defaultSizes(e.target.value).join(', ');}if(e.target.name==='heroPhoto'&&e.target.files[0]){try{$('#hero-preview').src=await photoData(e.target.files[0]);}catch(err){e.target.value='';toast(err.message);}}if(e.target.name==='photo'&&e.target.files[0]){try{$('#upload-preview').src=await photoData(e.target.files[0]);$('#upload-preview').classList.remove('hidden');}catch(err){e.target.value='';toast(err.message);}}});
document.addEventListener('submit',async e=>{
e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));const submit=f.querySelector('button.primary');if(submit)submit.disabled=true;
try{
if(f.classList.contains('order-workflow-form')&&owner){const result=await api('/api/orders/'+f.dataset.order,{method:'PATCH',body:{action:f.dataset.step,...v}});await syncOwner();renderOwner();toast(result.warning||({confirm:'Delivery quote saved. Create a Razorpay link next.','payment-link':'Payment link saved and emailed.','paid':'Payment recorded. Book the shipment next.','dispatch':'Tracking saved and emailed.'})[f.dataset.step]);}
if(f.id==='search-form'){query=v.search.trim();updateProducts();$('#collection').scrollIntoView({behavior:'smooth'});}
if(f.id==='reset-form'){pendingOtp=await api('/api/reset-password',{method:'POST',body:v});otpDialog();}
if(f.id==='policies-form'&&owner){await api('/api/policies',{method:'POST',body:v});await syncCatalog();toast('Shop policies saved.');}
if(f.id==='customer-form'){pendingOtp=await api(authMode==='register'?'/api/register':'/api/login',{method:'POST',body:{...v,role:'customer'}});otpDialog();}
if(f.id==='otp-form'){if(!pendingOtp)throw new Error('Request a new code first.');const result=await api('/api/verify-email',{method:'POST',body:{challengeId:pendingOtp.challengeId,code:v.code}});customer=result.user;pendingOtp=null;$('#modal').close();if(isOwner&&customer.role==='owner'){owner=true;await syncOwner();renderOwner();}else storefront();toast('Email verified. Welcome, '+customer.name+'.');}
if(f.id==='owner-form'){const result=await api('/api/login',{method:'POST',body:{...v,role:'owner'}});if(result.challengeId){pendingOtp=result;otpDialog();}else{customer=result.user;owner=true;await syncOwner();renderOwner();}}
if(f.id==='inquiry-form'){const result=await api('/api/inquiries',{method:'POST',body:{...v,ids:f.dataset.ids.split(',').filter(Boolean)}});modal(`<span class="eyebrow">ENQUIRY SENT</span><h2>Thank you for reaching out.</h2><p>${result.warning?esc(result.warning):result.preview?'For this localhost preview, your enquiry is saved in data/mail-outbox.jsonl.':'Your enquiry has been emailed to the JJ TrendZ owner.'} We’ll use the contact details you provided to get back to you.</p><button class="primary full" data-action="close">Keep exploring</button>`);}
if(f.id==='settings-form'&&owner){await api('/api/settings',{method:'POST',body:{contact:v}});await syncCatalog();toast('Contact details updated.');}
if(f.id==='checkout-settings-form'&&owner){await api('/api/checkout-settings',{method:'POST',body:v});await syncOwner();await syncCatalog();toast('Payment and delivery settings updated.');}
if(f.id==='hero-copy-form'&&owner){await api('/api/hero-copy',{method:'POST',body:v});await syncCatalog();renderOwner();toast('Homepage wording updated.');}
if(f.id==='hero-form'&&owner){const file=v.heroPhoto;if(!file?.size)throw new Error('Choose a hero photograph.');const image=await preparePhoto(await photoData(file));await api('/api/hero',{method:'POST',body:{image}});await syncCatalog();renderOwner();toast('Homepage image updated.');}
if(f.id==='password-form'){await api('/api/password',{method:'POST',body:v});f.reset();toast('Password updated.');}
if(f.id==='bulk-form'&&owner){const tiers=[...f.querySelectorAll('.tier-row')].map(row=>({quantity:row.querySelector('[name=quantity]').value,discount:row.querySelector('[name=discount]').value}));bulk=await api('/api/bulk',{method:'POST',body:{tiers}});toast('Bulk pricing updated.');}
if(f.id==='product-form'&&owner){
  const old=ownerProducts.find(p=>p.id===f.dataset.id),colors=parseOptions(v.colors,'colours'),sizes=parseOptions(v.sizes,'sizes');
  if(!editorPhotos.length)throw new Error('Add at least one product photo.');
  const stock={};for(const input of f.querySelectorAll('[data-stock-key]'))stock[input.dataset.stockKey]=input.value===''?null:Number(input.value);
  for(const color of colors)for(const size of sizes){const key=stockKey(color,size);if(!(key in stock))stock[key]=null;}
  const relatedIds=[...f.querySelectorAll('[name=related]:checked')].map(input=>input.value),pairWithIds=[...f.querySelectorAll('[name=pairWith]:checked')].map(input=>input.value);
  const product=await api('/api/products',{method:'POST',body:{id:old?.id,revision:Number(f.dataset.revision||0),name:v.name,category:v.category,collection:v.collection,occasion:v.occasion,featuredRank:Number(v.featuredRank),price:Number(v.price),oldPrice:Number(v.oldPrice),saleStart:v.saleStart,saleEnd:v.saleEnd,caption:v.caption,badge:v.badge,images:await preparePhotos(editorPhotos),colors,sizes,stock,status:v.status,material:v.material,plating:v.plating,dimensions:v.dimensions,included:v.included,care:v.care,dispatchNote:v.dispatchNote,relatedIds,pairWithIds}});
  await syncCatalog();await syncOwner();$('#modal').close();renderOwner();toast(product.status==='draft'?'Draft saved.':'Product is live on the storefront.');
}
if(f.id==='order-form'){let attempt=read('checkout-attempt',null);const fingerprint=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({...v,items:cartItems().map(p=>({id:p.id,quantity:p.quantity,color:p.color,size:p.size}))}))))].map(b=>b.toString(16).padStart(2,'0')).join('');if(!attempt||attempt.fingerprint!==fingerprint){attempt={fingerprint,key:crypto.randomUUID()};persist('checkout-attempt',attempt);}const {order}=await api('/api/orders',{method:'POST',body:{...v,idempotencyKey:attempt.key,items:cartItems().map(p=>({id:p.id,quantity:p.quantity,color:p.color,size:p.size}))}});bag=[];persist('bag',bag);persist('checkout-attempt',null);await syncCatalog();storefront();modal(`<span class="eyebrow">ORDER PLACED</span><h2>Thank you, ${esc(customer.name)}.</h2><p>Order #${esc(order.id.slice(0,8).toUpperCase())} is saved. Your pieces are reserved.</p>${order.paymentMethod==='UPI'?upiPaymentPanel(order):'<p>JJ TrendZ will confirm your delivery charge and send a Razorpay payment link.</p>'}<button class="secondary full" data-action="orders">View my orders</button>`);}
}catch(err){const error=f.querySelector('[role=alert]');if(error)error.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.filterRemove){
    const key=b.dataset.filterRemove;
    if(key==='color')colorFilter='';if(key==='size')sizeFilter='';
    if(key==='material')materialFilter='';if(key==='occasion')occasionFilter='';
    if(key==='price-min')priceMin='';if(key==='price')priceMax='';if(key==='stock')stockOnly=false;if(key==='sale')saleOnly=false;
    updateProducts();
  }
  if(b.dataset.gallery!==undefined){
    const current=$('[data-add]'),p=products.find(item=>item.id===current?.dataset.add),index=Number(b.dataset.gallery),src=p?.images?.[index];
    if(src){$('#detail-photo').src=src;document.querySelectorAll('[data-gallery]').forEach(el=>el.classList.toggle('active',el===b));}
  }
  const index=Number(b.dataset.photoRemove??b.dataset.photoUp??b.dataset.photoDown);
  if(b.dataset.photoRemove!==undefined){editorPhotos.splice(index,1);renderEditorPhotos();}
  if(b.dataset.photoUp!==undefined&&index>0){[editorPhotos[index-1],editorPhotos[index]]=[editorPhotos[index],editorPhotos[index-1]];renderEditorPhotos();}
  if(b.dataset.photoDown!==undefined&&index<editorPhotos.length-1){[editorPhotos[index+1],editorPhotos[index]]=[editorPhotos[index],editorPhotos[index+1]];renderEditorPhotos();}
});
document.addEventListener('change',async e=>{
  const target=e.target;
  if(['chosen-color','chosen-size'].includes(target.id)){const p=products.find(item=>item.id===$('[data-add]')?.dataset.add);if(p)refreshAvailability(p);}
  if(target.name==='photos'&&target.files?.length){
    try{if(editorPhotos.length+target.files.length>5)throw new Error('Use up to five product photos.');
      const added=await Promise.all([...target.files].map(photoData));editorPhotos.push(...added);renderEditorPhotos();
    }catch(error){toast(error.message);}finally{target.value='';}
  }
  if(target.closest('#product-form')&&['colors','sizes','category'].includes(target.name))renderStockInputs();
  if(target.name==='related'||target.name==='pairWith'){
    const checked=[...target.closest('fieldset').querySelectorAll('input:checked')];if(checked.length>4){target.checked=false;toast('Choose up to four products.');}
  }
  if(target.id==='filter-material'){materialFilter=target.value;updateProducts();}
  if(target.id==='filter-occasion'){occasionFilter=target.value;updateProducts();}
  if(target.id==='filter-price-min'){priceMin=target.value;updateProducts();}
  if(target.id==='filter-price'){priceMax=target.value;updateProducts();}
  if(target.id==='filter-stock'){stockOnly=target.checked;updateProducts();}
  if(target.id==='filter-sale'){saleOnly=target.checked;updateProducts();}
});
window.addEventListener('resize',()=>{if(matchMedia('(min-width:701px)').matches&&$('.filter-panel'))$('.filter-panel').open=true;});
await initialise();
setInterval(async()=>{
  const list=$('#customer-orders');
  if(!list||!$('#modal').open||customer?.role!=='customer')return;
  try{const data=await api('/api/orders');const snapshot=JSON.stringify(data.orders);if(customerOrderSnapshot!==snapshot){customerOrderSnapshot=snapshot;list.innerHTML=orderCards(data.orders);}}catch{/* Refresh again after the next interval. */}
},5000);
async function preparePhoto(source){return hostedUploads&&source.startsWith('data:')?(await api('/api/uploads',{method:'POST',body:{image:source}})).image:source;}
async function preparePhotos(sources){for(let i=0;i<sources.length;i++)sources[i]=await preparePhoto(sources[i]);return sources;}
async function api(path,{method='GET',body}={}){const r=await fetch(path,{method,headers:method!=='GET'?{'Content-Type':'application/json'}:{},body:method!=='GET'?JSON.stringify(body||{}):undefined});const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed.');if(path==='/api/catalog')hostedUploads=!!data.hostedUploads;return data;}
async function syncCatalog(){const data=await api('/api/catalog');products=data.products;contact=data.contact;bulk=data.bulk;policies=data.policies||{};heroImage=data.heroImage||'/assets/hero.jpg';heroCopy=data.heroCopy||heroCopy;checkoutSettings={...checkoutSettings,...data.checkout};normalizeBag();}
async function syncOwner(){const data=await api('/api/owner');inquiries=data.inquiries;orders=data.orders;ownerProducts=data.products||[];checkoutSettings=data.checkout||checkoutSettings;heroCopy=data.heroCopy||heroCopy;}
async function initialise(){try{await syncCatalog();const {user}=await api('/api/me');customer=user;owner=user?.role==='owner';if(isOwner){if(owner)await syncOwner();renderOwner();}else storefront();setInterval(async()=>{try{const before=JSON.stringify([products,contact,bulk,heroImage,heroCopy,checkoutSettings]);await syncCatalog();if(isOwner&&owner){const previous=JSON.stringify([orders,inquiries,ownerProducts]);await syncOwner();if((previous!==JSON.stringify([orders,inquiries,ownerProducts])||before!==JSON.stringify([products,contact,bulk,heroImage,heroCopy,checkoutSettings]))&&!$('#modal').open&&!['settings','bulk','payment','homepage'].includes(adminTab))renderOwner();}else if(!isOwner&&before!==JSON.stringify([products,contact,bulk,heroImage,heroCopy,checkoutSettings])){if(!$('#modal').open)storefront();else if($('#modal').querySelector('.quantity-input'))listModal('bag');}}catch{/* Retry on the next refresh. */}},5000);}catch(err){$('#app').innerHTML=`<main class="owner-login"><h1>Let’s reconnect.</h1><p>${esc(err.message)}</p><a class="primary" href="/">Try again</a></main>`;}}
function bulkModal(){modal(`<span class="eyebrow">MORE TO LOVE, MORE TO SAVE</span><h2>Beautiful in bulk.</h2><p>For celebrations, gifting, and your business. Mix and match pieces across the collection. Discounts apply to the total number of pieces in your bag.</p><div class="bulk-tiers">${bulk.tiers.length?bulk.tiers.map(t=>`<div><strong>${t.quantity}+ pieces</strong><span>${t.discount}% off</span></div>`).join(''):'<p>Contact us for a personalised bulk quote.</p>'}</div><p>Add your favourites to your bag, choose quantities, and see your savings instantly.</p><button class="primary full" data-action="shop">Build your order ${icon('arrow')}</button><br><br><button class="secondary full" data-action="bag">View my bag</button>`);}
function bulkSettings(){return `<h3>Bulk pricing, your way.</h3><p>Discounts apply to the total piece count across an order, after product sale prices. The highest qualifying tier applies. Orders keep the price agreed when they were placed.</p><form id="bulk-form"><div id="tier-list">${bulk.tiers.map(t=>tierRow(t)).join('')}</div><button type="button" class="secondary" id="add-tier">+ Add discount tier</button><br><br><button class="primary">Save bulk discounts</button></form>`;}
function paymentSettingsForm(){return `<h3>Payment & delivery</h3><p>Customers can pay by UPI as soon as an in-stock order is placed. The QR and payment button use the discounted product total plus this flat delivery charge. Existing orders keep their original amount and payee.</p><form id="checkout-settings-form"><div class="row"><label class="field">UPI ID<input name="upiId" required maxlength="320" value="${esc(checkoutSettings.upiId)}" placeholder="yourname@bank"></label><label class="field">Payee name shown in UPI<input name="payeeName" required maxlength="80" value="${esc(checkoutSettings.payeeName)}"></label></div><label class="field">Flat delivery charge (₹)<input name="deliveryFee" type="number" min="0" max="99999" step="1" required value="${checkoutSettings.deliveryFee}"><small>₹0 means free delivery. Set this before accepting orders.</small></label><p class="form-error" role="alert"></p><button class="primary">Save payment settings ${icon('check')}</button></form><p class="form-note">A UPI QR opens the customer's payment app. The website cannot verify payment automatically; check the received payment before marking an order paid or dispatching it.</p>`;}
function homepageSettingsForm(){return `<h3>Homepage wording</h3><p>Edit the words in the main banner. The two headline fields appear on separate lines.</p><form id="hero-copy-form"><label class="field">Small heading<input name="eyebrow" required maxlength="80" value="${esc(heroCopy.eyebrow)}"></label><div class="row"><label class="field">Headline, first line<input name="headline" required maxlength="100" value="${esc(heroCopy.headline)}"></label><label class="field">Headline, highlighted line<input name="highlight" required maxlength="100" value="${esc(heroCopy.highlight)}"></label></div><label class="field">Supporting text<textarea name="description" required maxlength="400">${esc(heroCopy.description)}</textarea></label><p class="form-error" role="alert"></p><button class="primary">Save homepage wording ${icon('check')}</button></form>`;}
function tierRow(t={quantity:10,discount:5}){return `<div class="tier-row row"><label class="field">Minimum pieces<input name="quantity" type="number" min="2" max="9999" required value="${t.quantity}"></label><label class="field">Discount (%)<input name="discount" type="number" min="0" max="80" step="0.1" required value="${t.discount}"></label><button type="button" class="text-link remove-tier">Remove tier</button></div>`;}
document.addEventListener('click',e=>{if(e.target.closest('#add-tier')){if(document.querySelectorAll('.tier-row').length>=5){toast('You can set up to five tiers.');return;}$('#tier-list').insertAdjacentHTML('beforeend',tierRow());}if(e.target.closest('.remove-tier'))e.target.closest('.tier-row').remove();});
function checkout(){
  if(customer?.role==='owner'){toast('Sign in with a customer account to place an order.');return;}
  if(!customer){authMode='login';account();toast('Sign in or create an account to place your order.');return;}
  const t=cartTotal();if(!cartItems().length)return;
  if(cartItems().some(item=>item.unavailable)){listModal('bag');toast('Check unavailable choices before ordering.');return;}
  modal(`<span class="eyebrow">YOUR NEXT BEAUTIFUL MOMENT</span><h2>Place your order.</h2><p>${t.quantity} pieces · Stock will be reserved when your order is placed.</p><div class="price-summary"><p><span>Products</span><strong>${money(t.subtotal)}</strong></p>${t.discount?`<p class="savings"><span>Bulk discount · ${t.discount}%</span><strong>−${money(t.bulkSavings)}</strong></p>`:''}<p><span>Delivery</span><strong>${money(t.deliveryFee)}</strong></p><p class="summary-total"><span>Total to pay</span><strong>${money(t.payableTotal)}</strong></p></div><form id="order-form"><label class="field">Phone number<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label>${hostedUploads?'<label class="field">Delivery PIN code<input name="pincode" inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6" required autocomplete="postal-code"></label>':''}<label class="field">Delivery address<textarea name="address" required maxlength="500" autocomplete="street-address"></textarea></label><label class="field">Order notes (optional)<textarea name="note" maxlength="1000" placeholder="Gift packaging, event date, sizing preferences…"></textarea></label><fieldset class="payment-choice"><legend>How would you like to pay?</legend><label><input type="radio" name="paymentMethod" value="UPI" checked> Pay by UPI now · QR or payment app</label><label><input type="radio" name="paymentMethod" value="Razorpay"> Request a Razorpay payment link</label></fieldset><p class="form-error" role="alert"></p><button class="primary full">Place order ${icon('arrow')}</button></form><p class="form-note">Your UPI amount includes the flat delivery charge. JJ TrendZ verifies payment manually before dispatch. Choosing Razorpay means the owner will send a separate link after confirmation.</p>`);
}
async function showOrders(){try{const data=await api('/api/orders');customerOrderSnapshot=JSON.stringify(data.orders);modal(`<span class="eyebrow">YOUR JJ TRENDZ JOURNEY</span><h2>Your orders</h2><div id="customer-orders">${orderCards(data.orders)}</div>`,true);}catch(err){toast(err.message);}}
function upiPaymentPanel(o){return `<div class="upi-payment"><strong>Pay ${money(o.payableTotal)} by UPI</strong><p>Scan with any UPI app, or tap the button on your phone. Confirm the payee and amount in your app before approving.</p><img class="upi-qr" src="/api/orders/${encodeURIComponent(o.id)}/qr" alt="UPI QR code for order ${esc(o.id.slice(0,8).toUpperCase())}"><div class="upi-payee">${esc(o.upiPayeeName)} · ${esc(o.upiPayeeId)}</div><a class="primary full" href="${esc(o.upiUri)}">Open UPI app · ${money(o.payableTotal)} ${icon('arrow')}</a><p class="form-note">Payment does not update automatically. JJ TrendZ will verify receipt before dispatch. Please avoid paying the same order twice.</p></div>`;}
function orderWorkflow(o,admin){
  if(o.status==='Cancelled')return '<p class="order-step">This order was cancelled. No payment is due.</p>';
  if(admin){
    if(o.paymentMethod==='UPI'&&o.status==='Confirmed'&&o.paymentStatus==='Awaiting payment')return `<div class="order-workflow"><strong>Check the UPI payment</strong><p>Customer was asked to pay <b>${money(o.payableTotal)}</b> to ${esc(o.upiPayeeName)} (${esc(o.upiPayeeId)}). Reference: ${esc(o.upiReference)}. Verify the actual receipt in your UPI or bank app before marking paid.</p><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="paid"><label class="field">Received payment reference (optional)<input name="paymentReference" maxlength="100" placeholder="UPI transaction ID"></label><p class="form-error" role="alert"></p><button class="primary">I verified payment · Mark paid ${icon('check')}</button></form><button class="text-link cancel-order" data-cancel-order="${esc(o.id)}">Cancel unpaid order</button></div>`;
    if(o.paymentMethod!=='UPI'&&(o.status==='Pending confirmation'||o.status==='Confirmed'&&!Number.isInteger(o.deliveryFee)))return `<div class="order-workflow"><strong>1 · Confirm stock and delivery</strong><p>Check the requested pieces and delivery address. Enter the final delivery charge before creating a Razorpay link.</p><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="confirm"><label class="field">Delivery charge (₹)<input name="deliveryFee" type="number" min="0" max="99999" step="1" required value="0"></label><p class="form-error" role="alert"></p><button class="primary">Confirm order and quote ${icon('arrow')}</button></form><button class="text-link cancel-order" data-cancel-order="${esc(o.id)}">Cancel order</button></div>`;
    if(o.paymentMethod!=='UPI'&&o.status==='Confirmed'&&!o.paymentLink)return `<div class="order-workflow"><strong>2 · Create a Razorpay Payment Link</strong><p>Create a link in your Razorpay dashboard for <b>${money(o.payableTotal??o.total)}</b>, then paste the generated https://rzp.io/i/ link here. Saving it emails the customer.</p><details class="quote-edit"><summary>Change delivery charge</summary><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="confirm"><label class="field">Delivery charge (₹)<input name="deliveryFee" type="number" min="0" max="99999" step="1" required value="${o.deliveryFee}"></label><p class="form-error" role="alert"></p><button class="secondary">Update delivery charge</button></form></details><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="payment-link"><label class="field">Razorpay Payment Link<input name="paymentLink" type="url" required maxlength="500" placeholder="https://rzp.io/i/..."></label><p class="form-error" role="alert"></p><button class="primary">Save and email payment link ${icon('arrow')}</button></form><button class="text-link cancel-order" data-cancel-order="${esc(o.id)}">Cancel order</button></div>`;
    if(o.paymentMethod!=='UPI'&&o.status==='Confirmed'&&o.paymentStatus!=='Paid')return `<div class="order-workflow"><strong>3 · Check payment in Razorpay</strong><p><a class="order-link" href="${esc(o.paymentLink)}" target="_blank" rel="noopener noreferrer">Open payment link ↗</a> · ${o.paymentEmailSentAt?'Email sent to customer':'Email not sent yet'}</p><div class="order-actions"><button class="secondary" data-email-order="${esc(o.id)}">Resend link email</button><button class="text-link" data-cancel-order="${esc(o.id)}">Cancel order</button></div><p>Only mark paid after Razorpay shows the full <b>${money(o.payableTotal??o.total)}</b> payment as received. Opening the link does not confirm payment.</p><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="paid"><label class="field">Razorpay payment reference (optional)<input name="paymentReference" maxlength="100" placeholder="pay_..."></label><p class="form-error" role="alert"></p><button class="primary">I verified payment · Mark paid ${icon('check')}</button></form></div>`;
    if(o.status==='Confirmed'&&o.paymentStatus==='Paid')return `<div class="order-workflow"><strong>4 · Create a manual Shiprocket order</strong><p>After booking the shipment in Shiprocket, enter its carrier and tracking number. The customer will see them and receive an email.</p><form class="order-workflow-form" data-order="${esc(o.id)}" data-step="dispatch"><div class="row"><label class="field">Carrier / courier<input name="carrier" required maxlength="80" placeholder="Shiprocket / courier name"></label><label class="field">Tracking number<input name="trackingNumber" required maxlength="100"></label></div><label class="field">Tracking link (optional)<input name="trackingUrl" type="url" maxlength="500" placeholder="https://..."></label><p class="form-error" role="alert"></p><button class="primary">Mark dispatched and email tracking ${icon('arrow')}</button></form></div>`;
    return `<div class="order-workflow"><strong>Shipment booked</strong><p>${esc(o.carrier||'Courier')} · ${esc(o.trackingNumber||'Tracking not entered')}${o.trackingUrl?` · <a class="order-link" href="${esc(o.trackingUrl)}" target="_blank" rel="noopener noreferrer">Track parcel ↗</a>`:''}</p><p>${o.trackingEmailSentAt?'Tracking email sent to customer':'Tracking email not sent yet'}</p><button class="secondary" data-email-tracking="${esc(o.id)}">Resend tracking email</button></div>`;
  }
  if(o.status==='Pending confirmation')return '<p class="order-step">We are checking availability and delivery cost. No payment is due yet.</p>';
  if(o.status==='Dispatched')return `<div class="order-workflow"><strong>Your parcel is on its way</strong><p>${esc(o.carrier||'Courier')} · Tracking number: <b>${esc(o.trackingNumber||'Ask us for tracking')}</b></p>${o.trackingUrl?`<a class="secondary" href="${esc(o.trackingUrl)}" target="_blank" rel="noopener noreferrer">Track your parcel ↗</a>`:''}</div>`;
  if(o.paymentStatus==='Paid')return '<p class="order-step">Payment confirmed. We are preparing your order for dispatch.</p>';
  if(o.paymentMethod==='UPI'&&o.paymentStatus==='Awaiting payment')return upiPaymentPanel(o);
  if(o.paymentLink)return `<div class="order-workflow"><strong>Your payment link is ready</strong><p>Check that Razorpay shows <b>${money(o.payableTotal??o.total)}</b> before paying. Your order will show as paid after JJ TrendZ verifies the payment.</p><a class="primary" href="${esc(o.paymentLink)}" target="_blank" rel="noopener noreferrer">Pay securely with Razorpay ↗</a></div>`;
  return '<p class="order-step">Your order and delivery cost are confirmed. Your secure payment link is coming soon.</p>';
}
function orderCards(list,admin=false){return list.length?list.slice().reverse().map(o=>`<article class="inquiry order-card"><div class="section-head"><div><small>${esc(new Date(o.created).toLocaleString('en-IN'))}</small><h3>Order #${esc(o.id.slice(0,8).toUpperCase())}</h3></div><span class="status-pill">${esc(o.status==='Confirmed'&&o.paymentStatus==='Paid'?'Paid · preparing dispatch':o.status)}</span></div>${admin?`<p><strong>${esc(o.name)}</strong> · ${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.address)}${o.pincode?' · PIN '+esc(o.pincode):''}</p>`:''}${o.items.map(i=>`<p>${esc(i.name)}${i.color?' · '+esc(i.color):''}${i.size?' · '+esc(i.size):''} <strong>× ${i.quantity}</strong> <span class="order-price">${money(i.price*i.quantity)}</span></p>`).join('')}<div class="order-totals"><p><span>${o.discount?'Products after '+o.discount+'% bulk discount':'Products'}</span><strong>${money(o.total)}</strong></p>${Number.isInteger(o.deliveryFee)?`<p><span>Delivery</span><strong>${money(o.deliveryFee)}</strong></p><p class="bag-total"><span>Total to pay</span><strong>${money(o.payableTotal??o.total+o.deliveryFee)}</strong></p>`:'<p class="bag-total"><span>Total before delivery</span><strong>${money(o.total)}</strong></p>'}</div>${o.needsPaymentReview?'<p class="form-error">Payment review needed: this reservation is over 24 hours old. Verify receipt before releasing stock.</p>':''}${o.note?`<p>Note: ${esc(o.note)}</p>`:''}${orderWorkflow(o,admin)}</article>`).join(''):'<div class="empty">'+icon('bag')+'<p>No orders yet. Your next favourite is waiting.</p></div>';}
